-- ===================== 虚影尖塔 (instanceId 2912) =====================
addon.GuideData.raids["12.0"]["虚影尖塔"] = {
    ["元首阿福扎恩"] = { order = 1, type = "BOSS", tips = [=[{rt8}元首阿福扎恩{rt8}||[机制摘要] 暗影突进召唤小怪需转火；虚空裂隙为旋转光束；暗影崩塌需踩入圈内吸收；虚空印记点名后留下持续黑暗（驱散后残留DoT）。湮灭之怒为全团闪避技，虚空坠落造成击退，黑暗剧变是周期性全团AoE。||{rt1}必断/速杀：{rt1} 优先转火暗影突进召唤的小怪；湮灭之怒读条时全员散开闪避；暗影崩塌安排人员踩圈/分摊。||坦：棱光之爪（昏黑伤口）叠层换坦，留意黑暗伤口DoT。治疗：黑暗剧变与虚空坠落期间预铺团刷，处理虚空印记驱散后的残留黑暗。输出：转火add，躲好湮灭之怒与虚空裂隙，站位避开崩塌圈外。]=], tipsByDifficulty = {lfr = [=[机制判定宽松，暗影崩塌与虚空裂隙范围大、add数量少。跟着团队踩圈、转火小怪即可，湮灭之怒看到提示直接散开。]=], normal = [=[暗影突进召唤小怪立即转火，虚空裂隙绕圈躲避，暗影崩塌踩圈。湮灭之怒全员闪避，虚空坠落击退后快速归位。]=], heroic = [=[节奏更快，虚空印记与湮灭之怒叠加需提前分配踩圈与驱散职责。暗影崩塌与虚空裂隙同时段发生，注意分层站位。]=], mythic = [=[计时轴紧凑，暗影突进、虚空裂隙、暗影崩塌多线并发。精确分配踩圈人员与虚空印记驱散，湮灭之怒与虚空坠落连发时严格按预案闪避走位。]=]} },
    ["弗拉希乌斯"] = { order = 2, type = "BOSS", tips = [=[{rt8}弗拉希乌斯{rt8}||[机制摘要] 虚空吐息为正面喷吐；暗影之爪猛击近战范围高伤；原始咆哮全团震退/恐惧。寄生虫喷吐召唤小怪需转火，暗黑黏液在地上造成持续伤害。||{rt1}必断/速杀：{rt1} 寄生虫喷吐出的add优先转火；原始咆哮读条时集合减伤；虚空吐息正面躲避。||坦：暗影之爪猛击为高伤近战打击，主坦注意减伤覆盖，背后站位避免吐息。治疗：原始咆哮与暗黑黏液叠加期预铺团刷，关注被凝视（Fixate）玩家。输出：转火寄生虫add，躲开吐息正面与地上黏液，猛击时远离Boss近战位。]=], tipsByDifficulty = {lfr = [=[节奏慢，吐息与黏液判定宽松，add少。跟着团队躲正面、转火小怪即可。]=], normal = [=[吐息正面躲避，暗影之爪猛击换坦，原始咆哮集合减伤。寄生虫喷吐出add立即转火，清理地上黏液。]=], heroic = [=[吐息与猛击频率提升，原始咆哮与寄生虫喷吐叠加需分配打断/转火。黏液区域更大，注意走位空间。]=], mythic = [=[狂暴6分12秒，所有技能紧凑并发。精确换坦与减伤链，add与吐息同时段严格分配转火与走位，避免黏液覆盖站位。]=]} },
    ["陨落之王萨哈达尔"] = { order = 3, type = "BOSS", tips = [=[{rt8}陨落之王萨哈达尔{rt8}||[机制摘要] 周期性施放熵之瓦解（满能量大招）需注意规避。虚空汇聚生成法球，碎裂暮光为地上尖刺，碎裂投影需打断。专制号令留下污池，扭曲晦暗为全团DoT。||{rt1}必断/速杀：{rt1} 碎裂投影必须打断；熵之瓦解读条时全员规避/减伤；虚空汇聚法球及时处理。||坦：不稳定打击与压迫黑暗注意换坦与减伤，专制号令污池别站。治疗：扭曲晦暗持续掉血，熵之瓦解后团血压力最大，预铺团刷。输出：打断碎裂投影，转火虚空汇聚法球，躲尖刺与污池。]=], tipsByDifficulty = {lfr = [=[大招判定宽松，打断压力小，法球量少。跟着团队规避熵之瓦解、打断投影即可。]=], normal = [=[碎裂投影安排打断，熵之瓦解集合减伤，虚空汇聚法球转火。碎裂暮光尖刺与污池走位躲避。]=], heroic = [=[熵之瓦解与扭曲晦暗叠加，法球与污池数量增多。碎裂投影需双打断轮替，暮光尖刺密集。]=], mythic = [=[狂暴6分10秒，轴极紧凑。熵之瓦解后紧接多线机制，精确打断链与减伤分配，法球+污池+尖刺同屏时严格按预案分层站位。]=]} },
    ["威厄高尔和艾佐拉克"] = { order = 4, type = "BOSS", tips = [=[{rt8}威厄高尔和艾佐拉克{rt8}||[机制摘要] 双龙威厄高尔（虚空光束/禁区/恐惧吐息/维翼）与艾佐拉克（幽暗/虚空咆哮/拉克尖牙）交替施放。午夜烈焰触发转阶段，光辉壁垒为阶段转换点。擒握血盆大口为坦抓。||{rt1}必断/速杀：{rt1} 恐惧吐息点名走位躲避；虚空光束由坦背对；午夜烈焰后立刻处理转阶段机制；幽暗debuff及时驱散/分摊。||坦：虚空光束与维翼、拉克尖牙为高伤坦技，主坦换坦并背对团队；擒握血盆大口注意被抓时机。治疗：幽暗与虚空咆哮叠加期团血压力大，午夜烈焰后预铺团刷。输出：恐惧吐息点名散开，虚空咆哮法球分散，转阶段快速转火集火指定目标。]=], tipsByDifficulty = {lfr = [=[双龙机制宽松，光束与吐息判定大。跟着团队走位、驱散幽暗即可。]=], normal = [=[威厄高尔虚空光束/禁区/吐息与艾佐拉克幽暗/咆哮交替。午夜烈焰触发转阶段，光辉壁垒集合。恐惧吐息点名散开，幽暗及时驱散。]=], heroic = [=[转阶段更频繁，虚空光束与拉克尖牙同段需双坦分工。幽暗叠加更快，虚空咆哮法球需精准分散。]=], mythic = [=[多阶段紧凑，午夜烈焰与光辉壁垒连发，机制堆叠（吐息+光束+幽暗）并发。精确转阶段分工、驱散轮替与分散站位，严格按预案处理每波组合。]=]} },
    ["光盲先锋军"] = { order = 5, type = "BOSS", tips = [=[{rt8}光盲先锋军{rt8}||[机制摘要] 三名先锋军各自带光环（愤怒/虔诚/和平），轮流施放处决令、神圣风暴、神圣什一税、审判与提尔之怒。复仇者之盾与神圣鸣钟需躲避，神圣护盾需打破，灼热光辉为治疗压力。||{rt1}必断/速杀：{rt1} 处决令点名踩圈/接球；神圣鸣钟读条时躲开护盾冲锋；神圣风暴（龙卷）区域规避。提尔之怒与处决令叠加时优先处理。||坦：审判[红]/[蓝]为坦克高伤，换坦并减伤；神圣护盾安排打破。治疗：神圣什一税与灼热光辉持续团血压力，提尔之怒（吸收+处决）需预铺。输出：转火/打破神圣护盾，躲神圣风暴与鸣钟，处决令点名去接。]=], tipsByDifficulty = {lfr = [=[光环与处决令判定宽松，风暴区域小。跟着团队踩圈、躲风暴即可。]=], normal = [=[处决令点名接球/踩圈，神圣风暴龙卷规避，神圣鸣钟躲护盾。审判换坦，提尔之怒预铺减伤。]=], heroic = [=[三名首领机制叠加更多，神圣什一税与灼热光辉并发。处决令+审判同段需分配，神圣护盾更快刷新。]=], mythic = [=[狂热之灵加入，强化版神圣风暴/复仇者之盾/灼热光辉出现。精确分组处理三首领并发机制，强化龙卷与鸣钟躲避窗口极小，严格按预案分散与减伤。]=]} },
    ["宇宙之冠"] = { order = 6, type = "BOSS", tips = [=[{rt8}宇宙之冠{rt8}||[机制摘要] 分三阶段：P1银击箭点名、虚空掌控方尖碑、虚空喷吐大伤、虚空冠层治疗吸收、暗手（坦）、打断震颤、饕餮深渊走位；转场银击弹幕线。P2游侠队长印记、虚空追猎毒刺、虚空召唤add、宇宙壁垒、裂隙斩。P3吞噬宇宙换台、终结之相锁链、宇宙传送门大add。||{rt1}必断/速杀：{rt1} 打断震颤必须断；虚空喷吐大伤提前减伤；P2/P3虚空召唤与宇宙传送门add优先转火。暗手由坦处理，饕餮深渊区域避开。||坦：暗手（Morium）与裂隙斩（Vorelus）为坦克高伤，换坦减伤；饕餮深渊别站。治疗：虚空冠层吸收与虚空喷吐大伤团血压力，P2宇宙壁垒后集中团刷。输出：打断震颤，转火虚空召唤add与宇宙传送门大add，躲银击箭/弹幕线，规避方尖碑与饕餮深渊。]=], tipsByDifficulty = {lfr = [=[三阶段简化，方尖碑与弹幕判定宽松，add少。跟着团队走位、转火即可。]=], normal = [=[P1银击箭点名散开、方尖碑踩点、打断震颤、虚空喷吐减伤；转场躲弹幕线。P2处理印记/毒刺/召唤add/壁垒；P3换台与锁链分散。]=], heroic = [=[阶段转换更快，P2/P3 add与壁垒并发。终结之相锁链与吞噬宇宙换台需精准分配，方尖碑刷新更快。]=], mythic = [=[裂隙残像加入，P3多add同屏（暗手/震颤/饕餮深渊并发）。精确换台路线、锁链分散与add转火顺序，严格按预案分层处理三阶段叠加机制。]=]} },
}
