    ["午夜陨落"] = { order = 2, type = "BOSS", tips = [=[{rt8}午夜陨落{rt8}||[机制摘要] 多阶段：P1天堂双刃、黑暗类星体光束、死亡挽歌记忆游戏、黑暗符文点名、守护棱镜打断、天堂之枪（坦）。转场星裂与类星体。P2 galvanize光束、核心收割闪避、黑暗崩溃击退。P3黑暗大天使爆炸、黑暗星座、光之虹吸踩圈。||{rt1}必断/速杀：{rt1} 守护棱镜/终结棱镜必须打断；死亡挽歌/苍白交响曲记忆游戏全员跟队形；黑暗符文点名去接；光之虹吸踩圈。||坦：天堂之枪为坦克点名，主坦接枪并减伤；击退后归位。治疗：galvanize光束与核心收割期团血压力，大天使爆炸预铺减伤。输出：打断棱镜，记忆游戏紧跟，转阶段快速处理星裂点名，P3虹吸踩圈、星座分散。]=], tipsByDifficulty = {lfr = [=[多阶段简化，记忆游戏与光束判定宽松。跟着团队走位、打断即可。]=], normal = [=[P1双刃/类星体/挽歌/符文/棱镜打断/天堂之枪；转场躲星裂与类星体。P2 galvanize躲光束、核心收割闪避、黑暗崩溃击退；P3大天使爆炸减伤、星座分散、虹吸踩圈。]=], heroic = [=[阶段转换更快，记忆游戏与棱镜打断并发。P2击退与收割叠加，P3虹吸与星座同段需分组。]=], mythic = [=[苍白交响曲/终结棱镜与死亡安魂曲/天堂地狱加入，P3按队伍左/右分组处理星座与安魂曲。精确记忆游戏队形、打断链与分组踩圈，严格按预案执行多线。]=]} },
}
